@log_input_and_output
def get_csv_data(csv_file_path):
    """
    Gets antenna online monitoring data from csv file, excluding empty lines and elements.
    :param csv_file_path: absolute csv file path, including file extension, e.g.: "home/ute/antenna_monitoring.csv"
    :type csv_file_path: str

    :returns: list of data elements from csv file, excluding empty elements. e.g.:
            ["VSWR",
             "No data available",
             "RTWP (dBm)",
             "Radio module,Antenna/Port,RX carrier,="13.03.2024 21:34:14"
             "RMOD-1/RMOD_R-1(AVQL),PHYANT,NRCELL-1,-78.1"]
     :rtype: list(str)
    """
    with open(csv_file_path, "r", encoding='utf-8-sig') as f:
        reader = csv.reader(f)
        return [','.join(row) for row in reader if row]


@log_input_and_output
def convert_webui_results_to_csv_data_format(webui_results, runtime_rmod_id):
    """
    Converts antenna online monitoring data returned from selenium method 'get_monitored_values' to csv file data
    format returned by 'get_csv_data' function.
    :param webui_results: webui results returned from 'get_monitored_values' selenium method, e.g.:
                         {'VSWR': [],
                          'RTWP': [{'Radio module': 'RMOD-1(AVQL)',
                                    'Antenna/Port': 'PHYANT',
                                    'RX carrier': 'NRCELL-1',
                                    '13.03.2024 21:35:14': '-78.1',
                                    '13.03.2024 21:35:04': '-79'}]}
    :type webui_results: dict
    :param runtime_rmod_id: runtime id of radio modules which antenna online monitoring is performed on, e.g.: 1
    :type runtime_rmod_id: int or str

    :returns: list of data elements from webui results in csv data format, e.g.:
                         ['VSWR',
                          'No data available',
                          'RTWP (dBm)',
                          'Radio module,Antenna/Port,RX carrier,="13.03.2024 21:35:04",="13.03.2024 21:35:14"',
                          'RMOD-1/RMOD_R-1(AVQL),PHYANT,NRCELL-1,-79,-78.1']
    :rtype: list(str)
    """
    data_list = []
    for measurement, results in webui_results.items():
        measurement_unit_phrase = _get_measurement_unit_phrase(measurement)
        data_list.append(measurement + measurement_unit_phrase)

        add_headers = True
        if results:
            for result in results:
                headers, values = _get_headers_and_values_from_result(result, runtime_rmod_id)

                if add_headers:
                    data_list.append(headers)
                    add_headers = False
                data_list.append(values)
        else:
            data_list.append("No data available")

    return data_list


@log_input_and_output
def verify_data_time_shift_in_webui_results(webui_results, expected_time_shift=10):
    """
    Verifies if all webui results timestamps have expected time shift.
    :param webui_results: webui results returned from 'get_monitored_values' selenium method, e.g.:
                         {'VSWR': [],
                          'RTWP': [{'Radio module': 'RMOD-1(AVQL)',
                                    'Antenna/Port': 'PHYANT',
                                    'RX carrier': 'NRCELL-1',
                                    '13.03.2024 21:35:04': '-79',
                                    '13.03.2024 21:34:54': '-79.2',
                                    '13.03.2024 21:34:44': '-78.8'}]}
    :type webui_results: dict
    :param expected_time_shift: expected time shift in seconds, defaults to 10
    :type expected_time_shift: int

    :raises WebuiTimeShiftResultsError: when time stamp in webui results is no the same as expected.
    """
    for measurement, results in webui_results.items():
        if results:
            for result in results:
                time_indicators = [key for key in result if re.search('[0-3][0-9].[0-1][0-9].20[0-9][0-9]', key)]
                result_times = [datetime.strptime(time.replace(".", "/"), '%d/%m/%Y %H:%M:%S')
                                for time in time_indicators]
                result_times_shifts = [(result_times[0] - result_time).total_seconds() for result_time in result_times]
                if not _verify_time_shifts(time_list=result_times_shifts, expected_shift=expected_time_shift):
                    raise WebuiTimeShiftResultsError(f"Results time shift is not the same as excepted "
                                                     f"{expected_time_shift}s: {result}")


@log_input_and_output
def verify_last_measured_values_unavailability(webui_results):
    """
    Verifies if last measured values of webui results are unavailable. Values unavailability means that all results
    are special sign "-" instead of numeric value.
    :param webui_results: webui results returned from 'get_monitored_values' selenium method, e.g.:
                         {'VSWR': [],
                          'RTWP': [{'Radio module': 'RMOD-1(AVQL)',
                                    'Antenna/Port': 'PHYANT',
                                    'RX carrier': 'NRCELL-1',
                                    '13.03.2024 21:35:04': '-',
                                    '13.03.2024 21:34:54': '-79.2',
                                    '13.03.2024 21:34:44': '-78.8'}]}
    :type webui_results: dict

    :returns: True if results values are unavailable, False otherwise
    :rtype: bool
    """
    last_measurements = _get_last_measured_values(webui_results)
    for measurement in last_measurements.values():
        if measurement:
            for result in measurement:
                if result != "-":
                    return False
    return True


@log_input_and_output
def verify_measurements_during_l3_call(webui_results, cell_dist_name, connection, antenna_list):
    """
    Verifies if all supported measurements have proper values during L3call data transfer. All supported measurements
    values should be different than 0. Verifies for every dictionary with measurement if there is a result with
    timestamp. Additionally checks if every expected antenna has at least one result ('-' is a valid result).
    For antenna with 'TX' direction VSWR and ETP measurement is mandatory.
    For antenna with 'RX' direction RTWP and RSSI measurement is mandatory.
    :param webui_results: webui results returned from 'get_monitored_values' selenium method, e.g.:
                         {'VSWR': [],
                          'RTWP': [{'Radio module': 'RMOD-1(AVQL)',
                                    'Antenna/Port': 'PHYANT',
                                    'RX carrier': 'NRCELL-1',
                                    '13.03.2024 21:35:04': '-79',
                                    '13.03.2024 21:34:54': '-79.2'
                                    '13.03.2024 21:34:44': '-78.8'}]}
    :type webui_results: dict
    :param cell_dist_name: configuration dist name for cell (e.g. 'MRBTS-40615/NRBTS-40615/NRCELL-0')
    :type cell_dist_name: str
    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :param antenna_list: list of antennas which will be checked (e.g.: ['ANT1', 'ANT2'], ['PHYANT'])
    :type antenna_list: list of str
    :raises L3CallMeasurementsError: when result of measurement is not unavailable.
    """
    for measurement, results in webui_results.items():
        if results:
            antenna_set = set()
            for result in results:
                if 'Cells' in result.keys():
                    if _get_rx_carrier_name_from_cell_dist_name(cell_dist_name) not in result['Cells']:
                        continue
                if 'RX carrier' in result.keys():
                    if _get_rx_carrier_name_from_cell_dist_name(cell_dist_name) not in result['RX carrier']:
                        continue
                if 'Antenna/Port' in result.keys():
                    antenna_set.add(result['Antenna/Port'])

                timestamps = [key for key in result if re.search('[0-3][0-9].[0-1][0-9].20[0-9][0-9]', key)]
                if not timestamps and not (measurement == 'VSWR' and 'PHYANT' in antenna_list):
                    raise L3CallMeasurementsError(f"One of {measurement}'s result has no measurements")
                for timestamp in timestamps:
                    if result[timestamp] == "0":
                        raise L3CallMeasurementsError(f"Result measured during L3Call transfer is not correct: "
                                                      f"'{timestamp}'= '{result[timestamp]}'")
            _verify_if_measurement_is_per_antenna(
                measurement=measurement,
                antenna_set=antenna_set,
                antenna_list=antenna_list,
                cell_dist_name=cell_dist_name,
                connection=connection
            )


def prepare_antenna_list(antenna_list):
    """
    Prepares format of antenna list required in antenna online monitoring configuration.
    :param antenna_list: antenna list to configure antenna online monitoring, e.g.: 'PHYANT' or ['ANT1', 'ANT2']
    :type antenna_list: str or list

    :returns: converts and returns antenna_list if provided argument is non-list type, returns provided arguments
              without any changes if provided argument is list type, e.g.: returns ['PHYANT'] instead of 'PHYANT'
    :rtype: list
    """
    return antenna_list if isinstance(antenna_list, list) else [antenna_list]


@log_input_and_output
def verify_required_measurements_presence(webui_results, measurements, antenna_list):
    """
    Verifies if all supported measurements are present in webui results.
    :param webui_results: webui results returned from 'get_monitored_values' selenium method, e.g.:
                         {'VSWR': [],
                          'RTWP': [{'Radio module': 'RMOD-1(AREA)',
                                    'Antenna/Port': 'ANT1',
                                    'RX carrier': 'NRCELL-1',
                                    '13.03.2024 21:35:04': '-79',
                                    '13.03.2024 21:34:54': '-79.2'},
                                    {'Radio module': 'RMOD-1(AREA)',
                                    'Antenna/Port': 'ANT2',
                                    'RX carrier': 'NRCELL-1',
                                    '13.03.2024 21:35:04': '-79.5',
                                    '13.03.2024 21:34:54': '-79.9'}],
                          'ETP': []}
    :type webui_results: dict
    :param measurements: list of required measurements, e.g.:
                         ['VSWR', 'RTWP', 'RSSI', 'ETP']
    :type measurements: list of str
    :param antenna_list: list of used antennas in antenna online monitoring test, e.g. ['ANT1', 'ANT2', 'ANT3', 'ANT4']
    :type antenna_list: list of str
    :raises L3CallMeasurementsError: when result of measurement is empty.
    :raises MissingMeasurementError: when required type of measurement is not in results.
    """
    for measurement, results in webui_results.items():
        if measurement == 'VSWR' and 'PHYANT' in antenna_list:
            continue
        if not results:
            raise L3CallMeasurementsError(f"Result for {measurement} should not be empty")

    for measurement in measurements:
        if measurement not in webui_results.keys():
            raise MissingMeasurementError(f"{measurement} measurement should be included in results")


@log_input_and_output
def convert_csv_results_to_webui_results_format(monitored_values_from_csv):
    """
    Converts monitored values from csv (list of str) to webui get_monitored_value method's format.
    :param monitored_values_from_csv: results from csv file as a list os str from get_csv_data method, e.g.
           ['VSWR', 'No data available',
            'RTWP (dBm)', ('Radio module,Antenna/Port,RX carrier,="12.06.2024 01:37:47",="12.06.2024 01:37:57",'
                           '="12.06.2024 01:38:07",="12.06.2024 01:38:17",="12.06.2024 01:38:27",'
                           '="12.06.2024 01:38:37",="12.06.2024 01:38:47",="12.06.2024 01:38:57",'),
            'RMOD-1/RMOD_R-1(AQQE),PHYANT,NRCELL-0,-,-,-,-,-,-,-,-',
            'RSSI (dBm)', ('Radio module,Antenna/Port,RX carrier,="12.06.2024 01:37:47",="12.06.2024 01:37:57",'
                           '="12.06.2024 01:38:07",="12.06.2024 01:38:17",="12.06.2024 01:38:27",'
                           '="12.06.2024 01:38:37",="12.06.2024 01:38:47",="12.06.2024 01:38:57",'),
            'RMOD-1/RMOD_R-1(AQQE),PHYANT,NRCELL-0,-,-,-,-,-,-,-,-',
            'ETP (mW)', ('Radio module,Antenna/Port,RX carrier,="12.06.2024 01:37:47",="12.06.2024 01:37:57",'
                         '="12.06.2024 01:38:07",="12.06.2024 01:38:17",="12.06.2024 01:38:27",'
                         '="12.06.2024 01:38:37",="12.06.2024 01:38:47",="12.06.2024 01:38:57",'),
            'RMOD-1/RMOD_R-1(AQQE),PHYANT,NRCELL-0,-,-,-,-,-,-,-,-,']
    :type monitored_values_from_csv: list of str
    :returns: dictionary with measurement name as key and list of data and measured results
              like in get_monitored_value method's format, e.g:
              {'VSWR': [],
               'RTWP': [{'Radio module': 'RMOD-1/RMOD_R-1(AQQE)', 'Antenna/Port': 'PHYANT', 'RX carrier': 'NRCELL-0',
                         '12.06.2024 01:37:47': '-', '12.06.2024 01:37:57': '-', '12.06.2024 01:38:07': '-',
                         '12.06.2024 01:38:17': '-', '12.06.2024 01:38:27': '-', '12.06.2024 01:38:37': '-',
                         '12.06.2024 01:38:47': '-', '12.06.2024 01:38:57': '-'}],
               'RSSI': [{'Radio module': 'RMOD-1/RMOD_R-1(AQQE)', 'Antenna/Port': 'PHYANT', 'RX carrier': 'NRCELL-0',
                         '12.06.2024 01:37:47': '-', '12.06.2024 01:37:57': '-', '12.06.2024 01:38:07': '-',
                         '12.06.2024 01:38:17': '-', '12.06.2024 01:38:27': '-', '12.06.2024 01:38:37': '-',
                         '12.06.2024 01:38:47': '-', '12.06.2024 01:38:57': '-'}],
               'ETP': [{'Radio module': 'RMOD-1/RMOD_R-1(AQQE)', 'Antenna/Port': 'PHYANT', 'RX carrier': 'NRCELL-0',
                        '12.06.2024 01:37:47': '-', '12.06.2024 01:37:57': '-', '12.06.2024 01:38:07': '-',
                        '12.06.2024 01:38:17': '-', '12.06.2024 01:38:27': '-', '12.06.2024 01:38:37': '-',
                        '12.06.2024 01:38:47': '-', '12.06.2024 01:38:57': '-'}]}
    :rtype: dict
    """
    monitored_values = {}
    vswr_list = monitored_values_from_csv[
        monitored_values_from_csv.index('VSWR') + 1:monitored_values_from_csv.index('RTWP (dBm)')]
    rtwp_list = monitored_values_from_csv[
        monitored_values_from_csv.index('RTWP (dBm)') + 1:monitored_values_from_csv.index('RSSI (dBm)')]
    rssi_list = monitored_values_from_csv[
        monitored_values_from_csv.index('RSSI (dBm)') + 1:monitored_values_from_csv.index('ETP (mW)')]
    etp_list = monitored_values_from_csv[monitored_values_from_csv.index('ETP (mW)') + 1:]

    monitored_values['VSWR'] = _create_result_list(vswr_list)
    monitored_values['RTWP'] = _create_result_list(rtwp_list)
    monitored_values['RSSI'] = _create_result_list(rssi_list)
    monitored_values['ETP'] = _create_result_list(etp_list)

    return monitored_values


@log_input_and_output
def _get_last_measured_values(webui_results):
    """
    Get last result from all measurements.
    :param webui_results: webui results returned from 'get_monitored_values' selenium method, e.g.:
                         {'VSWR': [],
                          'RTWP': [{'Radio module': 'RMOD-1(AREA)',
                                    'Antenna/Port': 'ANT1',
                                    'RX carrier': 'NRCELL-1',
                                    '13.03.2024 21:34:54': '-79.2',
                                    '13.03.2024 21:35:04': '-79'},
                                    {'Radio module': 'RMOD-1(AREA)',
                                    'Antenna/Port': 'ANT2',
                                    'RX carrier': 'NRCELL-1',
                                    '13.03.2024 21:34:54': '-79.9',
                                    '13.03.2024 21:35:04': '-79.5'}],
                          'ETP': []}
    :type webui_results: dict

    :returns: dictionary with measurement name as key and list of last measured results as value, e.g:
              {'ETP': [], 'RTWP': ['-79', '-79.5'], 'VSWR': []}
    :rtype: dict
    """
    last_measurements = {}
    for measurement, results in webui_results.items():
        last_measurements[measurement] = []
        if results:
            for result in results:
                last_timestamp = [key for key in result if re.search('[0-3][0-9].[0-1][0-9].20[0-9][0-9]', key)][-1]
                last_measurements[measurement].append(result[last_timestamp])

    return last_measurements


@log_input_and_output
def _get_measurement_unit_phrase(measurement):
    """
    Gets measurement unit phrase existing in antenna online monitoring csv file results.
    :param measurement: name of measurement, one of following: "VSWR", "RTWP", "RSSI" or "ETP"
    :type measurement: str

    :returns: measurement unit phrase of antenna monitoring results form csv file, e.g.: " (dBm)" for "RSSI measurement"
    :rtype: str
    """
    measurement_unit_dict = {"VSWR": "", "RTWP": " (dBm)", "RSSI": " (dBm)", "ETP": " (mW)"}
    return measurement_unit_dict[measurement]


@log_input_and_output
def _get_hw_values(result, hw_keys, runtime_rmod_id):
    """
    Gets values of measurement headers based on provided hw keys, leaving aside results with timestamps headers.
    :param result: single result of measurement, e.g.:
                         {'Radio module': 'RMOD-1(AVQL)',
                          'Antenna/Port': 'PHYANT',
                          'RX carrier': 'NRCELL-1',
                          '13.03.2024 21:35:04': '-79',
                          '13.03.2024 21:34:54': '-79.2'}
    :type result: dict
    :param hw_keys: hw headers names of single measurement result, excluding timestamp headers e.g.:
                         ['Radio module', 'Antenna/Port', 'RX carrier']
    :type hw_keys: list(str)
    :param runtime_rmod_id: runtime rmod id, e.g.: 1
    :type runtime_rmod_id: int or str

    :returns: list of hw results from single measurement results, based on provided hw keys, e.g.:
              ['RMOD-1/RMOD_R-1(AVQL)', 'PHYANT', 'NRCELL-1']
    :rtype: list
    """
    hw_values = []
    for hw_key in hw_keys:
        hw_value = result[hw_key]
        if "RMOD-" in result[hw_key]:
            hw_value = _convert_radio_module_value(hw_value, runtime_rmod_id)
        hw_values.append(hw_value)
    return hw_values


@log_input_and_output
def _convert_radio_module_value(webui_rmod_name, runtime_rmod_id):
    """
    Converts radio module name included in antenna monitoring results from webui format to csv format.
    Csv format name contains additional rmod runtime id phrase (/RMOD_R-1 where 1 is runtime_rmod_id).
    :param webui_rmod_name: name of radio module from antenna monitoring webui results, e.g.: 'RMOD-1(AREA)'
    :type webui_rmod_name: str
    :param runtime_rmod_id: runtime if of radio module, e.g.: 1
    :type runtime_rmod_id: str or int

    :returns: converted webui rmod name from webui format to csv format, e.g.: 'RMOD-1/RMOD_R-1(AREA)'
    :rtype: str
    """
    rmod_id = webui_rmod_name.split("(")[0].split("-")[-1]
    rmod_name = webui_rmod_name.split("(")[-1][:-1]
    return f'RMOD-{rmod_id}/RMOD_R-{runtime_rmod_id}({rmod_name})'


@log_input_and_output
def _verify_time_shifts(time_list, expected_shift):
    """
    Verifies if all elements of time_list have the same particular time shift.
    :param time_list: list of time shifts determined in relation to the first time value, e.g.:
                      [0.0, 10.0, 20.0, 30.0, 40.0, 50.0]
    :type time_list: list
    :param expected_shift: expected time shift in seconds
    :type expected_shift: str or int

    :returns: True if all elements of time_list have proper time shifts, False otherwise.
    :rtype: bool
    """
    for index in range(len(time_list) - 1):
        if not (time_list[index + 1] - time_list[index] == int(expected_shift)):
            return False
    return True


def _get_headers_and_values_from_result(result, runtime_rmod_id):
    """
    Gets headers and values from webui results as text lines (the same as csv antenna monitoring results format).
    Timestamps headers are reversed to keep the same timestamp order as in csv format.
    Radio module name in values is converted to csv format also (e.g.: 'RMOD-1(AVQL)' converted to
                                                                 'RMOD-1/RMOD_R-1(AVQL)'
    :param result: one of measured result from webui antenna monitoring results, e.g.:
                  {'Radio module': 'RMOD-1(AVQL)',
                  'Antenna/Port': 'PHYANT',
                  'RX carrier': 'NRCELL-1',
                  '13.03.2024 21:34:24': '-79.3',
                  '13.03.2024 21:34:14': '-78.1'}
    :type result: dict
    :param runtime_rmod_id: runtime if of radio module, e.g.: 1
    :type runtime_rmod_id: str or int

    :returns: headers and values of webui results returned as strings in tuple, e.g.:
              ('Radio module,Antenna/Port,RX carrier,="13.03.2024 21:34:14",="13.03.2024 21:34:24"',
               'RMOD-1/RMOD_R-1(AVQL),PHYANT,NRCELL-1,-78.1,-79.3')
    :rtype: tuple (str, str)
    """
    data_regex = '[0-3][0-9].[0-1][0-9].20[0-9][0-9]'
    hw_keys = [key for key in result if not re.search(data_regex, key)]
    data_keys = [key for key in result if re.search(data_regex, key)]
    data_keys.reverse()
    data_keys_csv_format = [f'="{item}"' for item in data_keys]

    hw_values = _get_hw_values(result, hw_keys, runtime_rmod_id)
    data_values = [result[data_key] for data_key in data_keys]

    headers = ",".join(hw_keys + data_keys_csv_format)
    values = ",".join(hw_values + data_values)

    return headers, values


@log_input_and_output
def _verify_if_measurement_is_per_antenna(measurement, antenna_set, antenna_list, cell_dist_name, connection):
    if 'PHYANT' in antenna_list:
        if measurement != 'VSWR':
            if not _verify_if_every_antenna_has_result(antenna_set, antenna_list):
                raise L3CallMeasurementsError(f"Not every antenna has result for {measurement}'s measurement")
    else:
        if measurement == 'VSWR' or measurement == 'ETP':
            antenna_lines_one_direction = get_active_antennas_for_cell_with_specific_direction(
                cell_dist_name=cell_dist_name, connection=connection, direction='TX'
            )
        else:
            antenna_lines_one_direction = get_active_antennas_for_cell_with_specific_direction(
                cell_dist_name=cell_dist_name, connection=connection, direction='RX'
            )
        antenna_list_one_direction = _get_simple_antennas_list(antenna_lines_one_direction)
        antenna_list_one_direction_for_test = [
            antenna for antenna in antenna_list_one_direction if antenna in antenna_list]
        if not _verify_if_every_antenna_has_result(antenna_set, antenna_list_one_direction_for_test):
            raise L3CallMeasurementsError(f"Not every antenna has result for {measurement}'s measurement")


@log_input_and_output
def _get_rx_carrier_name_from_cell_dist_name(cell_dist_name):
    """
    Returns carrier's name from dist name for cell.

    :param cell_dist_name: configuration dist name for cell (e.g. 'MRBTS-40615/NRBTS-40615/NRCELL-0')
    :type cell_dist_name: str
    :returns: carrier's name (e.g. 'NRCELL-0')
    :rtype: str
    """
    return cell_dist_name.split('/')[-1]


@log_input_and_output
def _verify_if_every_antenna_has_result(antenna_set, antenna_lines):
    """
    Verifies if all used antennas in 'antenna online monitoring' test have no empty result by comparing antenna's set
    with list of used antennas.

    :param antenna_set: set of antenna's name for which measurement is found (e.g. {'ANT3', 'ANT1'})
    :type antenna_set: set of str
    :param antenna_lines: list of antennas for which measurement should be found (e.g. ['ANT1', 'ANT3'])
    :type antenna_lines: list of str
    :returns: True if all antennas from antenna_lines are found in antenna_set, False otherwise.
    :rtype: bool
    """
    return all(antenna in antenna_set for antenna in antenna_lines)


@log_input_and_output
def _create_result_list(csv_measurements):
    result = []
    result_keys = csv_measurements[0].split(',')
    csv_measurements.pop(0)
    for csv_measurement in csv_measurements:
        measurement_dict = {}
        csv_measurement_list = csv_measurement.split(',')
        for ind in range(len(result_keys)):
            if result_keys[ind].startswith('='):
                measurement_dict[result_keys[ind][2:-1]] = csv_measurement_list[ind]
            else:
                if result_keys[ind] == 'Supported TX bands':
                    bands_count = len(csv_measurement_list) - len(result_keys)
                    bands = ','.join(csv_measurement_list[ind:ind + bands_count + 1])
                    measurement_dict[result_keys[ind]] = bands
                    for band_ind in range(bands_count):
                        csv_measurement_list.pop(ind + band_ind + 1)
                else:
                    measurement_dict[result_keys[ind]] = csv_measurement_list[ind]
        result.append(measurement_dict)
    return result


@log_input_and_output
def _get_simple_antennas_list(antenna_lines):
    """
    Converts runtime/active antenna's names to simple form - ANT1

    :param antenna_lines: list of runtime/active antenna's names
           (e.g. ['/MRBTS-1/RAT-1/RUNTIME_VIEW-4/MRBTS_R-4/EQM_R-4/APEQM_R-1/RMOD_R-2/ANTL_R-1',
                  '/MRBTS-1/RAT-1/RUNTIME_VIEW-4/MRBTS_R-4/EQM_R-4/APEQM_R-1/RMOD_R-2/ANTL_R-3'])
    :type antenna_lines: list of str
    :returns:list of simple antenna's names. (e.g. ['ANT1', 'ANT3'])
    :rtype: list of str
    """
    return [antenna_line.split('/')[-1].replace('L_R-', '') for antenna_line in antenna_lines]
